class SimDIO(SimDIOBase):
    """A plain boolean DIO honoring the real I/O direction.

    ``Output`` DIOs are settable (get + set), exactly like the real control
    records. ``Input`` DIOs are read-only signals — on real hardware they
    are driven by the field wiring, so `set` raises `DIOReadOnlyError` —
    with a sim-only ``sim_value`` control to poke them in simulation (there
    is no real hardware to drive them here).
    """

    def __init__(self, config: DIOConfig, name: str = "") -> None:
        self.config = config
        self._sim_value_subscribed = False
        with self.add_children_as_readables(Format.HINTED_SIGNAL):
            if self.hw_settable:
                self.value = soft_signal_rw(bool, config.initial_value)
            else:
                self.value, self._set_value = soft_signal_r_and_setter(
                    bool, config.initial_value
                )
        if not self.hw_settable:
            # Sim-only control (will NOT exist on real hardware)
            self.sim_value = soft_signal_rw(bool, config.initial_value)
        with self.add_children_as_readables(Format.CONFIG_SIGNAL):
            self.io_type, _ = soft_signal_r_and_setter(str, config.io_type)
        super().__init__(name=name)

    @property
    def hw_settable(self) -> bool:
        """True when the real DIO is writable (``I/O Type`` is Output)."""
        return self.config.io_type == "Output"

    async def connect(
        self,
        mock: bool = False,
        timeout: float = DEFAULT_TIMEOUT,
        force_reconnect: bool = False,
    ) -> None:
        await super().connect(
            mock=mock, timeout=timeout, force_reconnect=force_reconnect
        )
        if not self.hw_settable and not self._sim_value_subscribed:
            self.sim_value.subscribe_reading(self._on_sim_value)
            self._sim_value_subscribed = True

    def _on_sim_value(self, readings: dict[str, Reading[bool]]) -> None:
        (reading,) = readings.values()
        self._set_value(bool(reading["value"]))

    def set(self, value: bool) -> AsyncStatus:
        """Set the DIO, so ``bps.mv(dio, True)`` works — Outputs only."""
        if not self.hw_settable:
            raise DIOReadOnlyError(
                f"{self.config.label}: this DIO is a hardware "
                f"{self.config.io_type or 'Input'} and cannot be set on real "
                "hardware; in sim, poke it via the sim-only `sim_value` "
                "signal instead"
            )
        return self.value.set(bool(value))

class SimDIOBase(StandardReadable):
    """Common base for simulated DIOs; holds the parsed config."""

    config: DIOConfig

class SimDevices:
    """All simulated devices, in per-subsystem namespaces."""

    ais: dict[str, SimAI] = field(default_factory=dict)
    dios: dict[str, SimDIOBase] = field(default_factory=dict)
    motors: dict[str, SimLVMotor] = field(default_factory=dict)
    detectors: dict[str, Device] = field(default_factory=dict)
    config: BeamlineConfig = field(default_factory=BeamlineConfig)
    sim_config: SimConfig = field(default_factory=SimConfig)

    def all_devices(self) -> Iterator[Device]:
        yield from self.ais.values()
        yield from self.dios.values()
        yield from self.motors.values()
        yield from self.detectors.values()

    def manifest(self) -> dict[str, Any]:
        """JSON-safe description of every device, for data-driven UIs."""
        return build_manifest(self)

    def stop_updates(self) -> None:
        """Cancel all background updater tasks (for orderly teardown)."""
        for ai in self.ais.values():
            ai.stop_updates()

    @property
    def beam_current(self) -> SimBeamCurrent | None:
        for ai in self.ais.values():
            if isinstance(ai, SimBeamCurrent):
                return ai
        return None

def count(detectors, num: int = 1, delay: float = 0.0, *, md: dict = None):
    yield from _light_off()
    yield from _count(detectors, num=num, delay=delay, md=md)

def load_beamline_config(config_dir: Path | str) -> BeamlineConfig:
    """Parse all three config files found in ``config_dir``."""
    config_dir = Path(config_dir)
    return BeamlineConfig(
        ais=load_ai_configs(config_dir / AI_FILENAME),
        dios=load_dio_configs(config_dir / DIO_FILENAME),
        motors=load_motor_configs(config_dir / MOTOR_FILENAME),
    )

import { useMemo } from 'react';
import {
    OphydSimProvider,
    createOphydSimTransport,
    createOphydSim,
    motor,
} from '@/lib/ophyd-sim';
import { OphydTransportProvider } from '@/api/ophyd/OphydTransportProvider';
import useOphydPVSocket from '@/api/ophyd/useOphydPVSocket';
import DeviceControllerBox from '@/components/DeviceControllerBox';

// 1. Build a sim. Keep it stable across renders (module scope or useMemo).
const sim = createOphydSim({
    devices: [motor({ name: 'IOC:m1', limits: [-10, 10], velocity: 2, units: 'mm' })],
});

// 2. A leaf that talks to the sim through the normal Ophyd PV hook.
function MotorControl() {
    const { devices, handleSetValueRequest, toggleDeviceLock } = useOphydPVSocket([
        'IOC:m1',
        'IOC:m1.RBV',
    ]);

    return (
        <DeviceControllerBox
            device={devices['IOC:m1']}
            deviceRBV={devices['IOC:m1.RBV']}
            handleSetValueRequest={handleSetValueRequest}
            handleLockClick={toggleDeviceLock}
        />
    );
}

// 3. Wrap the tree: OphydSimProvider starts/stops the tick loop;
//    OphydTransportProvider routes the PV hooks at the sim instead of a WebSocket.
export function Example() {
    const transport = useMemo(() => createOphydSimTransport(sim), []);
    return (
        <OphydSimProvider sim={sim}>
            <OphydTransportProvider transport={transport}>
                <MotorControl />
            </OphydTransportProvider>
        </OphydSimProvider>
    );
}

