class BeamlineMotor(SynAxis):
    """A soft positioner with engineering units and a finite slew rate."""

    def __init__(self, *, name, units="mm", slew=None, precision=4, **kwargs):
        super().__init__(name=name, precision=precision, **kwargs)
        self._units = units
        self.slew = slew          # engineering units / s, None -> instant
        self.simulate_timing = False

    def describe(self):
        desc = super().describe()
        for key in desc:
            desc[key]["units"] = self._units
        return desc

    def set(self, value):
        old = self.readback.get()
        st = super().set(value)
        if self.simulate_timing and self.slew:
            time.sleep(abs(float(value) - float(old)) / self.slew)
        return st
